#!/usr/bin/env python3
"""Writes the five tabular deliverables of MS-02 local_validation from curated rows + derived_metrics.json.
Run after derive_metrics.py. Every numeric value in 'value' columns is either (a) quoted from a source with locator,
or (b) taken from derived_metrics.json (this-study calculation)."""
import csv, json, pathlib
HERE = pathlib.Path(__file__).resolve().parent
D = json.loads((HERE/"derived_metrics.json").read_text())
dist = D["distance_cell_centre_to_study_extent_km"]
DATE = "2026-11-15"
def write(name, header, rows):
    with open(HERE/name, "w", newline="", encoding="utf-8-sig") as f:
        w = csv.writer(f); w.writerow(header)
        for r in rows:
            assert len(r) == len(header), (name, r[0], len(r), len(header))
            w.writerow(r)
    print(name, len(rows))

